mapper.select:
 	select  COUNTER_ID id,
 			COUNTER_ID text
 	from MST_COUNTER_PARTY
 	where COUNTER_TYPE = #{counterType}

			and (COUNTER_ID like concat(concat('%',#{search}),'%')
			or COUNTER_NAME like concat(concat('%',#{search}),'%'))


			and MST_COUNTER_PARTY.COUNTER_NAME = #{counterName}


			and MST_COUNTER_PARTY.COUNTER_ID = #{initValue}

 	select  COUNTER_NAME id,
 			COUNTER_NAME text
 	from MST_COUNTER_PARTY
 	where COUNTER_TYPE = #{counterType}

			and (COUNTER_ID like concat(concat('%',#{search}),'%')
			or COUNTER_NAME like concat(concat('%',#{search}),'%'))


			and MST_COUNTER_PARTY.COUNTER_ID = #{counterId}


			and MST_COUNTER_PARTY.COUNTER_NAME = #{initValue}

		select FIN_PRODUCT.FINPROD_ID id, FINPROD_MARKET_ID || ':' || FINPROD_ABBR text 
		from FIN_PRODUCT, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY
		where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		  and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd}
		  and FIN_PRODUCT.P_FINPROD_ID IS NULL
		  and FIN_PRODUCT.PROFIT_TYPE = '02'

		  	and FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus}



		  and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID


			and (FIN_PRODUCT.FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
    			or FIN_PRODUCT.FINPROD_ABBR like concat(concat('%',#{search}),'%'))


			AND FIN_PRODUCT_ADD.ISSUE_STATUS IN (#{ISSUE_STATUS_01, jdbcType = VARCHAR}, #{ISSUE_STATUS_03, jdbcType = VARCHAR})



         		and FIN_PRODUCT.FINPROD_ID = #{initValue}



			  	  and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.VDATE vdate, case when FIN_PRODUCT_ADD.DEAL_MODE in ('01', '11') then FIN_PRODUCT.MDATE when FIN_PRODUCT_ADD.DEAL_MODE in ('10', '12') and to_date(#{vdate}, 'yyyy-MM-dd') > FIN_PRODUCT.VDATE then (select FIN_OPEN_PLAN.OPEN_VDATE from FIN_OPEN_PLAN where FIN_OPEN_PLAN.FINPROD_ID = #{finprodId} and FIN_OPEN_PLAN.OPEN_TYPE IN ('01', '03') and to_date(#{vdate}, 'yyyy-MM-dd') >= FIN_OPEN_PLAN.OPEN_DATE_STR and FIN_OPEN_PLAN.OPEN_DATE_END >= to_date(#{vdate}, 'yyyy-MM-dd')) when FIN_PRODUCT_ADD.DEAL_MODE in ('10', '12') and FIN_PRODUCT.VDATE >= to_date(#{vdate}, 'yyyy-MM-dd') then (select * from (select FIN_OPEN_PLAN.OPEN_VDATE from FIN_OPEN_PLAN where FIN_OPEN_PLAN.FINPROD_ID = #{finprodId} and FIN_OPEN_PLAN.OPEN_TYPE IN ('01', '03') order by OPEN_MDATE) where rownum = 1) else null end mdate, FIN_PRODUCT_ADD.TMPL_ID tmplId, FIN_PRODUCT.FINPROD_NAME finprodName, FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
FIN_PRODUCT_ADD.PORTFOLIO_ID ptlId, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType,
FIN_RATE_INFO.INT_TYPE calcType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT_ADD.INVESTMENT_CYCLE investmentCycle,/*投资周期*/ FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG profitFlag, FIN_PRODUCT.ENTRUST_TYPE entrustType, FIN_PRODUCT.ENTRUSTER entruster, FIN_RATE_INFO.RATE * 100 yield, PRD_SALE_PARAM.FIRST_SALE_VDATE firstSaleVdate, PRD_SALE_PARAM.FIRST_SALE_MDATE firstSaleMdate, PRD_SALE_PARAM.CONTINUE_FLAG continueFlag, FIN_PRODUCT_ADD.CLOSE_DAYS closeDays, FIN_PRODUCT.TERM_DAYS termDays, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_RATE_INFO.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment, FIN_PRODUCT_ADD.PUR_SPEED purSpeed, FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investNature, FIN_PRODUCT_ADD.SALE_MODE saleMode,
case when (select count(*) from TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID = #{finprodId})>0 then 'C2' else 'C1' end ps from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID /*left join PA_FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID*/ left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = #{branch}
left join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE) left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.FINPROD_ID = #{finprodId}
and FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}

mapper.sql:
select distinct '01' effectStatus, TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId, TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_NAME finprodName, TRD_FIN_PRODUCT_DEAL_TOTAL.CCY ccy, TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE vdate, TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE mdate, FIN_RATE_INFO.BASIS basis, TRD_FIN_PRODUCT_DEAL_TOTAL.LAST_AMT lastAmt, TRD_FIN_PRODUCT_DEAL_TOTAL.LAST_AMT_SUB lastAmtSub, TRD_FIN_PRODUCT_DEAL_TOTAL.LAST_RED lastRed, TRD_FIN_PRODUCT_DEAL_TOTAL.CURRENT_SUB currentSub, TRD_FIN_PRODUCT_DEAL_TOTAL.ACCOUNTING_AMT accountingAmt, FIN_PRODUCT_ADD.DEAL_MODE dealMode, PRD_SALE_PARAM.CONTINUE_FLAG continueFlag /*add by yejiejie 2019-2-21 start*/ ,pa_trd_product_deal.customers_begin_num customersBeginNum ,pa_trd_product_deal.customers_add_num customersAddNum ,trd_Product_Deal.ps ps /*add by yejiejie 2019-2-21 end*/ /*add by gcl 2019-3-19 start*/ ,trd_Product_Deal.REMARK remark /*add by gcl 2019-3-19 end*/ from TRD_FIN_PRODUCT_DEAL_TOTAL inner join FIN_PRODUCT on TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} LEFT join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE)
left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID /*add by yejiejie 2019-2-21 start*/ left join trd_Product_Deal on trd_Product_Deal.totle_trade_id = TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID left join pa_trd_product_deal on pa_trd_product_deal.trade_id = trd_Product_Deal.trade_id /*add by yejiejie 2019-2-21 end*/ where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = #{finprodId}
and TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = #{tradeId}

select distinct #{effectStatus} effectStatus, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID tradeId, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_NAME finprodName, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.CCY ccy, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.VDATE vdate, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.MDATE mdate, FIN_RATE_INFO.BASIS basis, null lastAmt, null lastAmtSub, null lastRed, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.SHARE_AMT currentSub, WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FPRICE_AMT accountingAmt, FIN_PRODUCT_ADD.DEAL_MODE dealMode, PRD_SALE_PARAM.CONTINUE_FLAG continueFlag /*add by yejiejie 2019-2-21 start*/ ,WFL_PA_TRD_PRODUCT_DEAL.customers_begin_num customersBeginNum ,WFL_PA_TRD_PRODUCT_DEAL.customers_add_num customersAddNum ,WFL_TRD_PRODUCT_DEAL.ps ps /*add by yejiejie 2019-2-21 end*/ /*add by gcl 2019-3-19 start*/ ,WFL_TRD_PRODUCT_DEAL.REMARK remark /*add by gcl 2019-3-19 end*/ ,WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.WORKFLOW_ID workflowId from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL inner join FIN_PRODUCT on WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} LEFT join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE)
left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID /*add by yejiejie 2019-2-21 start*/ left join WFL_TRD_PRODUCT_DEAL on WFL_TRD_PRODUCT_DEAL.totle_trade_id = WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID left join WFL_PA_TRD_PRODUCT_DEAL on WFL_PA_TRD_PRODUCT_DEAL.trade_id = WFL_TRD_PRODUCT_DEAL.trade_id /*add by yejiejie 2019-2-21 end*/ where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = #{finprodId}
and WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = #{tradeId}

mapper.select:
select 
count(*) 
from FIN_TRADE_PRODUCT 
where 
FIN_TRADE_PRODUCT.FINPROD_ID = #{finprodId}

and FIN_TRADE_PRODUCT.BRANCH = #{branch}

SELECT count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL
where IS_CANCEL = #{yesOrNoN} 
and TRADE_STATUS = #{tradeStatus01}  and TOTLE_TRADE_ID != #{tradeId}
and FINPROD_ID = #{finprodId} and PS = #{ps01}
